import{_ as o,l as i,o as e,c as s,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"FPU 惰性保存","description":"","frontmatter":{"title":"FPU 惰性保存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fpu-lazy.md","filePath":"cs/fpu-lazy.md","lastUpdated":1789023840000}'),h={name:"cs/fpu-lazy.md"};function m(P,a,u,_,f,E){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="fpu-惰性保存" tabindex="-1">FPU 惰性保存 <a class="header-anchor" href="#fpu-惰性保存" aria-label="Permalink to &quot;FPU 惰性保存&quot;">​</a></h1><div class="epigraph"><p>大多数线程切换并不碰到浮点寄存器；等到下一次真正用 FPU 再保存上一所有者，比每次切换都搬几百字节更便宜。</p><footer>—— 据 Love, Linux Kernel Development；Tanenbaum MOS 对上下文切换代价的整理</footer></div><p><a href="/cs/kernel-stack">上一课</a>让通用寄存器与 trapframe 跟着内核栈走。向量与浮点寄存器组很大，每次<a href="/cs/context-switch">上下文切换</a>都保存会抬高切换税，而大量内核路径与整数进程根本不用它们。缺口是<strong>惰性保存</strong>：记住 FPU 的当前所有者，切走时只设「下一线程使用则陷阱」，直到陷阱才把状态写入上一任务的 PCB。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每次切换都存还原 FPU，<a href="/cs/scheduling-metrics">调度指标</a>里的吞吐被无谓搬运压住。若永不保存，两个用浮点的线程会互相覆盖。惰性：切换时关 FPU（或标脏），下一线程执行浮点指令则陷入内核，此时保存旧所有者、恢复新线程的 FPU 镜像、标记新所有者。缺口不是更大的内核栈，而是这条延迟到第一次使用才付的账。</p><p><span class="marginnote">内核本身少用浮点；一旦内核用了，必须急切保存用户 FPU 或禁止在该路径抢占，以免污染。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>PCB 里有 FPU 保存区与「内容是否有效」位。硬件：TS 一类标志使浮点指令陷阱。陷阱处理：存旧、恢复新、清标志、从陷阱返回重执行该指令。两个都不用 FPU 的线程之间，切换不碰 FPU 寄存器。</p>',8)),(e(),n(c,null,{default:r(()=>[p(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SW%5B%22%E5%88%87%E6%8D%A2%22%5D%20--%3E%20LAZY%5B%22%E4%B8%8D%E7%AB%8B%E5%8D%B3%E5%AD%98%20FPU%22%5D%0A%20%20LAZY%20--%3E%20USE%5B%22%E4%B8%8B%E4%B8%80%E7%BA%BF%E7%A8%8B%E7%94%A8%E6%B5%AE%E7%82%B9%22%5D%0A%20%20USE%20--%3E%20TRAP%5B%22%E9%99%B7%E9%98%B1%3A%20%E5%AD%98%E6%97%A7%E6%81%A2%E5%A4%8D%E6%96%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>信号递送若要给处理函数一个干净的浮点环境，可能被迫提前保存——点到即可，不写 ABI 全文。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>惰性把切换代价变成「用 FPU 的线程才付」。与 trapframe 的急切保存对照：通用寄存器每次陷入都可能被内核当临时量，必须当场存；FPU 内核通常碰不到。多核上每 CPU 记住所有者；迁移时要把所有权弄对，否则会恢复错核上的寄存器。本课不把 xsave 优化路径写完。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列举 AVX-512 状态组件的大小表，不讨论如何用浮点陷阱做侧信道。用户是否「应该」在信号处理里用浮点是 ABI 问题。idle 还没出场：没有可运行任务时 CPU 跑谁，下一课。</p><p>后课默认：FPU 可以惰性换。就绪队列空时仍要有一条可运行的内核线程，下一课讲 idle。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FPU/向量很大；切换时惰性，用到再换。</li><li>通用寄存器仍随 trapframe 急切保存。</li><li>无任务可跑时的 idle 线程是下一课。</li><li>出处：Love, <em>LKD</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',8))])}const U=o(h,[["render",m]]);export{B as __pageData,U as default};
